export type HoursBalanceBillingMethod = typeof HoursBalanceBillingMethod[keyof typeof HoursBalanceBillingMethod];


export const HoursBalanceBillingMethod = {
  SOLL: 'SOLL',
  IST: 'IST',
} as const;

export interface HoursBalance {
  userId: number;
  userName: string;
  plannedHours: number;
  actualHours: number;
  balance: number;
  workedHours: number;
  sickHours: number;
  /** Genommene Urlaubstage des gewählten Monats (Anzahl der Urlaubs-Schichten in diesem Monat). */
  vacationDaysTaken: number;
  /** Abgeleiteter Jahres-Verbrauch in Tagen (vacationHoursUsed / hoursPerDay des Team-Kontos, gerundet auf 0,1). */
  vacationDaysUsed: number;
  /** Resturlaub in Tagen (vacationDays - vacationDaysUsed), abgeleitet aus der Stunden-Buchhaltung. */
  vacationDaysRemaining: number;
  valuedHours: number;
  vacationFulfilledHours: number;
  totalFulfilledHours: number;
  nightHours: number;
  nightSurchargeHours: number;
  sundayHours: number;
  sundaySurchargeHours: number;
  holidayHours: number;
  holidaySurchargeHours: number;
  nightPercent: number;
  sundayPercent: number;
  holidayPercent: number;
  /** Angewandte Abrechnungsart dieser Zeile (SOLL = Plan, IST = Ist-Zeiten). */
  billingMethod: HoursBalanceBillingMethod;
  /**
     * Stundenlohn der Assistenzkraft (Premium-Lohnauswertung); null wenn nicht gesetzt/kein Zugriff.
     * @nullable
     */
  hourlyWage?: number | null;
  /**
     * Grundvergütung nach Abrechnungsart (billingMethod) = Summe(Stundenlohn * bewertete Stunden je Dienst, ggf. prozentual) + Festbeträge, plus Lohnfortzahlung (Stundenlohn * erfüllte Urlaubs-/Krankstunden). Nur Premium.
     * @nullable
     */
  basePay?: number | null;
  /**
     * Geldwert des Nachtzuschlags (Zuschlagsstunden nach Abrechnungsart inkl. Abwesenheits-Fortzahlung * Stundenlohn). Nur Premium.
     * @nullable
     */
  nightSurchargePay?: number | null;
  /**
     * Geldwert des Sonntagszuschlags (Zuschlagsstunden nach Abrechnungsart inkl. Abwesenheits-Fortzahlung * Stundenlohn). Nur Premium.
     * @nullable
     */
  sundaySurchargePay?: number | null;
  /**
     * Geldwert des Feiertagszuschlags (Zuschlagsstunden nach Abrechnungsart inkl. Abwesenheits-Fortzahlung * Stundenlohn). Nur Premium.
     * @nullable
     */
  holidaySurchargePay?: number | null;
  /**
     * Gesamtvergütung = basePay + Zuschläge. Nur Premium.
     * @nullable
     */
  totalPay?: number | null;
}

export type VacationBalanceMethod = typeof VacationBalanceMethod[keyof typeof VacationBalanceMethod];


export const VacationBalanceMethod = {
  bwavg: 'bwavg',
  factor: 'factor',
} as const;

/**
 * Quelle der Tages-Stunden-Bewertung eines ganztägigen Urlaubstags zum heutigen Stichtag: 13-Wochen-Schnitt (bwavg), Vertragsdaten (Wochenstunden ÷ Arbeitstage/Woche) oder Standardwert. Bei "contract" sollte die UI auf die Datenpflege der Arbeitstage/Woche hinweisen (Migrations-Default 5).
 */
export type VacationBalanceDailyHoursSource = typeof VacationBalanceDailyHoursSource[keyof typeof VacationBalanceDailyHoursSource];


export const VacationBalanceDailyHoursSource = {
  bwavg: 'bwavg',
  contract: 'contract',
  default: 'default',
} as const;

export interface VacationBalance {
  contractId: number;
  userId: number;
  /** Anspruch in Tagen (vacationHoursTotal / hoursPerDay, gerundet). */
  vacationDays: number;
  /** Verbrauchte Tage (vacationHoursUsed / hoursPerDay, gerundet, Anzeige). */
  vacationDaysUsed: number;
  vacationDaysRemaining: number;
  /** Gesamt-Urlaubsanspruch in Stunden (vacationDays * hoursPerDay). */
  vacationHoursTotal: number;
  /** Stundengenau verbrauchter Urlaub. */
  vacationHoursUsed: number;
  vacationHoursRemaining: number;
  /** Umrechnungsfaktor Stunden je Tag (Standard 8). */
  hoursPerDay: number;
  method: VacationBalanceMethod;
  /** Ersatzruhetage (§ 11 Abs. 3 ArbZG): Anzahl Feiertage mit bestaetigter Arbeit. */
  restDaysEarned?: number;
  /** Eingeloeste Ersatzruhetage (Anzahl Freizeitausgleich-Tage). */
  restDaysRedeemed?: number;
  /** Verbleibendes Ersatzruhetag-Guthaben (verdient − eingeloest). */
  restDaysBalance?: number;
  /** Ist das Ersatzruhetag-Konto für dieses Team aktiv? Bei false wird keine Feiertagsarbeit gutgeschrieben (restDaysEarned = 0). */
  ersatzruhetagEnabled?: boolean;
  /** Quelle der Tages-Stunden-Bewertung eines ganztägigen Urlaubstags zum heutigen Stichtag: 13-Wochen-Schnitt (bwavg), Vertragsdaten (Wochenstunden ÷ Arbeitstage/Woche) oder Standardwert. Bei "contract" sollte die UI auf die Datenpflege der Arbeitstage/Woche hinweisen (Migrations-Default 5). */
  dailyHoursSource?: VacationBalanceDailyHoursSource;
  /** Verwendete Stunden je Urlaubstag zum heutigen Stichtag. */
  dailyHours?: number;
  /**
     * Arbeitstage/Woche des aktiven Vertrags (null ohne Vertrag).
     * @nullable
     */
  contractWorkdaysPerWeek?: number | null;
  /**
     * Wochenstunden des aktiven Vertrags (null ohne Vertrag).
     * @nullable
     */
  contractWeeklyHours?: number | null;
}

